import type { DefaultIcon } from './default-icons';

/**
 * The pictures a browser's install sheet shows (RFC 0001 A1, `MANIFEST_SCREENSHOTS` in `src/pwa.ts`): core's sign-in
 * page with the default branding, at the sizes the manifest says. Kept in code, as the icons are, so the image needs
 * no folder of static files. Made by `apps/e2e/scripts/capture-screenshots.ts` against a built core; run it again when the
 * sign-in page changes enough to make them wrong.
 */
const NARROW =
  '';
const WIDE =
  '';

export const SCREENSHOTS: Readonly<Record<string, DefaultIcon>> = {
  'screenshot-narrow.png': { bytes: Buffer.from(NARROW, 'base64'), contentType: 'image/png' },
  'screenshot-wide.png': { bytes: Buffer.from(WIDE, 'base64'), contentType: 'image/png' },
};
